import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long x = nextLong(), y = nextLong();
        long[] a = new long[n];
        long maxA = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            maxA = Math.max(maxA, a[i]);
        }
        long extra = x - y, low = 0, high = (maxA + y - 1) / y;
        while (low < high) {
            long mid = (low + high) / 2, need = 0, base = mid * y;
            // Each task gets mid * y for free; the shortfall needs primary turns worth x - y each.
            for (long v : a) {
                if (v > base) need += (v - base + extra - 1) / extra;
                if (need > mid) break;
            }
            if (need <= mid) high = mid;
            else low = mid + 1;
        }
        System.out.println(low);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, x, y := nextInt(), nextInt(), nextInt()
	a := make([]int, n)
	maxA := 0
	for i := range a {
		a[i] = nextInt()
		maxA = max(maxA, a[i])
	}
	extra, low, high := x-y, 0, (maxA+y-1)/y
	for low < high {
		mid := (low + high) / 2
		need, base := 0, mid*y
		// Each task gets mid * y for free; the shortfall needs primary turns worth x - y each.
		for _, v := range a {
			if v > base {
				need += (v - base + extra - 1) / extra
			}
			if need > mid {
				break
			}
		}
		if need <= mid {
			high = mid
		} else {
			low = mid + 1
		}
	}
	fmt.Println(low)
}
